import 'dart:convert';
import 'dart:typed_data';

/// Only raster images generated by an explicitly enabled local plugin. SVG,
/// arbitrary data URLs and oversized payloads are never treated as images.
Uint8List? inlineImageBytes(String source) {
  if (!source.startsWith('data:image/')) return null;
  if (source.length > 7 * 1024 * 1024 ||
      !RegExp(r'^data:image/(png|jpeg|gif|webp);base64,').hasMatch(source)) {
    throw const FormatException('插件图片格式无效或超过 5 MB。');
  }
  final bytes = base64Decode(source.substring(source.indexOf(',') + 1));
  if (bytes.isEmpty || bytes.length > 5 * 1024 * 1024) {
    throw const FormatException('插件图片为空或超过 5 MB。');
  }
  return bytes;
}
